      },
      "requires": {
        "resources": [],
        "functions": []
      },
      "resources": [
        { "name": "a", "kind": "sync", "type": "Mutex", "mode": "Sync" },
        { "name": "b", "kind": "sync", "type": "Mutex", "mode": "Sync" },
        { "name": "hs", "kind": "sync", "type": "Semaphore", "mode": "Sync", "count": 1 },
        { "name": "done_a", "kind": "var", "type": "Var", "base": "Int", "init": "0" },
        { "name": "done_b", "kind": "var", "type": "Var", "base": "Int", "init": "0" },
        { "name": "out", "kind": "var", "type": "Var", "base": "Int", "init": "0" }
      ],
