          "body": [
            { "sid": "s1", "kind": "mutex_lock", "resource": "main::a" },
            { "sid": "s2", "kind": "mutex_lock", "resource": "main::b" },
            { "sid": "s3", "kind": "write_shared", "resource": "main::done_a", "expr": "1" },
            { "sid": "s4", "kind": "mutex_unlock", "resource": "main::b" },
            { "sid": "s5", "kind": "mutex_unlock", "resource": "main::a" },
            { "sid": "s6", "kind": "semaphore_release", "resource": "main::hs" },
            { "sid": "s7", "kind": "return" }
          ]
        },
        {
