            { "sid": "s2", "kind": "mutex_lock", "resource": "main::a" },
            { "sid": "s3", "kind": "mutex_lock", "resource": "main::b" },
            { "sid": "s4", "kind": "write_shared", "resource": "main::done_b", "expr": "1" },
            { "sid": "s5", "kind": "mutex_unlock", "resource": "main::b" },
            { "sid": "s6", "kind": "mutex_unlock", "resource": "main::a" },
            { "sid": "s7", "kind": "return" }
          ]
        },
        {
          "name": "c",
          "kind": "normal",
          "form": "closure",
          "body": [
            { "sid": "s1", "kind": "write_shared", "resource": "main::out", "expr": "1" },
            { "sid": "s2", "kind": "return" }
          ]
        }
      ]
    }
  ]
}
